// The telescoping sum, with the negative column aligned to the positive
// terms it cancels.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(300,260);
label("$+\frac{1}{1}$", (0,4.4), E);
label("$+\frac{1}{2}$", (0,3.3), E);
label("$\frac{1}{2}$", (5.2,3.3), W);
label("$+\frac{1}{3}$", (0,2.2), E);
label("$\frac{1}{3}$", (5.2,2.2), W);
label("$+\frac{1}{4}$", (0,1.1), E);
label("$\frac{1}{4}$", (5.2,1.1), W);
label("$+\frac{1}{5}$", (0,0.0), E);
label("$\frac{1}{5}$", (5.2,0.0), W);
label("$\frac{1}{6}$", (5.2,-1.1), W);
for (int i=0; i<4; ++i) {
  draw((0.9,3.3-1.1*i)--(1.5,3.3-1.1*i), dashed);
}
draw((4.5,0)--(4.5,4.4), gray);
label("the two survivors", (2.6,-2.3), S);

// Four outside-in pairings of the odd numbers, each summing to the same
// total.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,200);
for (int i=0; i<4; ++i) {
  real y = 1.5*(3-i);
  draw((0,y)--(2,y));
  draw((2,y)--(4,y));
  dot((0,y), black+2.5pt);
  dot((2,y), black+2.5pt);
  dot((4,y), black+2.5pt);
  label("$"+string(2*i+1)+"$", (0,y-0.1), S);
  label("$"+string(99-2*i)+"$", (4,y-0.1), S);
  label("$100$", (2,y+0.1), N);
}
label("every pair is worth the same", (2, -0.8), S);

examples.asymptoteSource:
// Lattice points in a triangular region, one row per value of the index.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(300,240);
for (int i=0; i<6; ++i) {
  for (int j=0; j<=i; ++j) {
    dot((0.7*j,0.7*i), black+2pt);
  }
}
draw((0,0)--(3.5,0));
draw((0,0)--(0,3.5));
draw((0,0)--(3.15,3.15), dashed);
label("$\sum$", (-0.6,1.75), E);
label("one row of dots per value of the index", (1.6,-0.7), S);
